package com.studentrental.controller;
import com.studentrental.model.*;import com.studentrental.repo.*;import com.studentrental.service.CurrentUser;
import org.springframework.http.*;import org.springframework.web.bind.annotation.*;import java.time.*;import java.time.temporal.ChronoUnit;import java.util.*;
@RestController @RequestMapping("/api/bookings")
public class BookingController{
 final BookingRepository bookings;final ItemRepository items;final CurrentUser current;
 public BookingController(BookingRepository b,ItemRepository i,CurrentUser c){bookings=b;items=i;current=c;}
 Map<String,Object> dto(Booking b){Map<String,Object> m=new LinkedHashMap<>();m.put("id",b.getId());m.put("itemId",b.getItem().getId());m.put("itemTitle",b.getItem().getTitle());m.put("imageUrl",b.getItem().getImageUrl()==null?"":b.getItem().getImageUrl());m.put("renterId",b.getRenter().getId());m.put("renterName",b.getRenter().getName());m.put("ownerId",b.getOwner().getId());m.put("ownerName",b.getOwner().getName());m.put("startDate",b.getStartDate());m.put("endDate",b.getEndDate());m.put("totalAmount",b.getTotalAmount());m.put("depositAmount",b.getDepositAmount());m.put("status",b.getStatus());m.put("createdAt",b.getCreatedAt());return m;}
 @GetMapping List<Map<String,Object>> all(){AppUser u=current.get();return bookings.findByRenterIdOrOwnerIdOrderByCreatedAtDesc(u.getId(),u.getId()).stream().map(this::dto).toList();}
 @PostMapping ResponseEntity<?> create(@RequestBody Map<String,String>b){try{RentalItem item=items.findById(Long.valueOf(b.get("itemId"))).orElseThrow();AppUser renter=current.get();LocalDate start=LocalDate.parse(b.get("startDate")),end=LocalDate.parse(b.get("endDate"));if(!item.isAvailable()||item.getOwner().getId().equals(renter.getId())||start.isBefore(LocalDate.now())||!end.isAfter(start))return ResponseEntity.badRequest().body(Map.of("message","Choose a valid date range and an available item you do not own."));long days=ChronoUnit.DAYS.between(start,end);Booking bk=new Booking();bk.setItem(item);bk.setRenter(renter);bk.setOwner(item.getOwner());bk.setStartDate(start);bk.setEndDate(end);bk.setTotalAmount(days*item.getPricePerDay());bk.setDepositAmount(item.getDeposit());return ResponseEntity.ok(dto(bookings.save(bk)));}catch(Exception e){return ResponseEntity.badRequest().body(Map.of("message","Could not create booking. Check item and dates."));}}
 @PatchMapping("/{id}/status") ResponseEntity<?> status(@PathVariable Long id,@RequestBody Map<String,String>b){Booking x=bookings.findById(id).orElse(null);if(x==null)return ResponseEntity.notFound().build();AppUser u=current.get();if(!x.getOwner().getId().equals(u.getId())&&!u.getRole().equals(Role.ADMIN))return ResponseEntity.status(403).build();try{Booking.Status s=Booking.Status.valueOf(b.get("status"));if(x.getStatus()!=Booking.Status.PENDING)return ResponseEntity.badRequest().body(Map.of("message","Only pending bookings can be decided"));if(s!=Booking.Status.APPROVED&&s!=Booking.Status.REJECTED)return ResponseEntity.badRequest().build();x.setStatus(s);return ResponseEntity.ok(dto(bookings.save(x)));}catch(Exception e){return ResponseEntity.badRequest().body(Map.of("message","Invalid status"));}}
 @PatchMapping("/{id}/return") ResponseEntity<?> returned(@PathVariable Long id){Booking x=bookings.findById(id).orElse(null);if(x==null)return ResponseEntity.notFound().build();AppUser u=current.get();if(!x.getOwner().getId().equals(u.getId())&&!x.getRenter().getId().equals(u.getId())&&!u.getRole().equals(Role.ADMIN))return ResponseEntity.status(403).build();if(x.getStatus()!=Booking.Status.APPROVED)return ResponseEntity.badRequest().body(Map.of("message","Only approved rentals can be completed"));x.setStatus(Booking.Status.COMPLETED);return ResponseEntity.ok(dto(bookings.save(x)));}
}
